        body:'১৩৪২ সালে ইলিয়াস শাহ্‌ বাংলার সিংহাসনে বসলে রাজনৈতিক স্থায়িত্বের সম্ভাবনার সূচনা ঘটে। এই রাজবংশ প্রথম পর্যায়ে ৭১ বছর রাজত্ব করে শান্তি ও শৃঙ্খলা স্থাপনে সচেষ্ট হন।'
