    theoryFacts:[
      {q:'রবীন্দ্রনাথ ও জাতীয় সংগীত — কী তথ্য জানা জরুরি?', a:'১৯০৫ সালে বঙ্গদর্শন পত্রিকায় প্রথম কবিতা হিসেবে প্রকাশিত হয়; কবিতাটির মোট চরণ ছিল-২৫টি; \'আমার সোনার বাংলা ও বাংলার মাটি বাংলার জল\' গান দুটি ১৯০৫ সালের বঙ্গভঙ্গের প্রেক্ষাপটে রচিত; গানটির সুরকার রবীন্দ্রনাথ নিজে (গগন হরকরার \'আমি কোথায় পাব তারে আমার মনের মানুষ যে রে\' বাউল গানটির সুরের অনুষঙ্গে গানটি রচিত); জাতীয় সংগীত \'আমার সোনার বাংলা\' গানটি রবীন্দ্রনাথের গীতবিতান কাব্যের \'স্বরবিতান\' অংশ থেকে নেয়া; গানটিতে বাংলার প্রকৃতির কথা প্রাধান্য পেয়েছে; ২৫ চরণের কবিতাটির প্রথম ১০ চরণ ১৯৭১ সালের ৩ মার্চ পল্টন ময়দানে ঘোষিত স্বাধীনতার ইশতিহারে বাংলাদেশের জাতীয় সংগীত হিসেবে গৃহীত হয়; ১৯৭২ সালের ১৬ ডি. থেকে বাংলাদেশের সংবিধানে এই গানকে জাতীয় সংগীতের মর্যাদা দেয়া হয়; রাষ্ট্রীয় অনুষ্ঠানে বাদ্যযন্ত্রে বাজানো হয়-প্রথম ৪ চরণ/লাইন; গানটির ইংরেজি অনুবাদ করেন-সৈয়দ আলী আহসান; ১৯৭০ সালে জহির রায়হানের বিখ্যাত চলচ্চিত্র জীবন থেকে নেয়া চলচ্চিত্রে এই গানের প্রথম চলচ্চিত্রায়ণ হয়'}
    ],
